import sys, math, itertools, random, bisect, heapq
from functools import lru_cache
from collections import Counter, defaultdict, deque
from pathlib import Path

def quadratic(text):
    x = list(map(int, text.split()))
    out = []
    memo = {}
    for n in x[1:]:
        if n in memo:
            out.append(memo[n])
            continue
        good = False
        if n >= 0:
            for y in range(math.isqrt(n // 3) + 1):
                v = n - 3 * y * y
                r = math.isqrt(v)
                if r * r == v:
                    good = True
                    break
        memo[n] = 'yes' if good else 'no'
        out.append(memo[n])
    return '\n'.join(out)
import sys
sys.stdout.write(quadratic(sys.stdin.read()) + '\n')

