def popcount_square(text):
    n = int(text)
    states = {(0, True): (1, 0, 0)}
    for bit in bin(n)[2:]:
        next_states = {}
        for ((_, tight), (count, ones, square)) in states.items():
            for b in range((int(bit) if tight else 1) + 1):
                key = (0, tight and b == int(bit))
                (c, o, s) = next_states.get(key, (0, 0, 0))
                next_states[key] = (c + count, o + ones + b * count, s + square + 2 * b * ones + b * count)
        states = next_states
    return str(sum((v[2] for v in states.values())))
import sys
