def winter(text):
    lines = text.splitlines()
    (n, m) = map(int, lines[0].split())
    choices = [sorted(set(map(lambda x: int(x) - 1, line.split()))) for line in lines[1:n + 1]]
    caps = list(map(int, lines[n + 1].split()))
    states = {(0,) * m: 1}
    for options in sorted(choices, key=len):
        nxt = defaultdict(int)
        for (counts, ways) in states.items():
            for j in options:
                if counts[j] < caps[j]:
                    key = counts[:j] + (counts[j] + 1,) + counts[j + 1:]
                    nxt[key] += ways
        states = nxt
    return str(sum(states.values()))
import sys
