import sys, math, itertools, random, bisect, heapq
from functools import lru_cache
from collections import Counter, defaultdict, deque
from pathlib import Path

def shortest(text):
    t = text.split()
    n = int(t[0])
    a = t[1:]
    start = a.index('S')
    end = a.index('E')
    q = deque([(start, 0)])
    seen = {start}
    while q:
        (i, d) = q.popleft()
        if i == end:
            return str(d)
        (r, c) = divmod(i, n)
        for (u, v) in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            j = u * n + v
            if 0 <= u < n and 0 <= v < n and (j not in seen) and (a[j] != '0'):
                seen.add(j)
                q.append((j, d + 1))
    return 'N'
import sys
sys.stdout.write(shortest(sys.stdin.read()) + '\n')

