NUMBERS=[18222,20124,20126,21463,21729,23559,23560,23562,23565,23665,23666,23667,25563,25568,25575,25576,25577,25578,25579,25581]
SAMPLE_DISPUTES={21729:'第二样例答案超过无限制单调路径上界',25576:'第一样例答案与本题自己的过程说明矛盾'}
def portfolio(text):
 x=list(map(int,text.split()));budget,k=x[:2];prices=[x[2+7*i:9+7*i] for i in range(k)];weights=[r[0] for r in prices];gains=[max(r)-r[0] for r in prices];dp=[-10**100]*(budget+1);choice=[-1]*(budget+1);dp[0]=0
 for i,(w,g) in enumerate(zip(weights,gains)):
  for spent in range(w,budget+1):
   if dp[spent-w]>-10**100 and dp[spent-w]+g>dp[spent]:dp[spent]=dp[spent-w]+g;choice[spent]=i
 spent=max(range(max(0,budget-min(weights)+1),budget+1),key=lambda b:dp[b]);out=[0]*k
 while spent:
  i=choice[spent]
  if i<0:raise ValueError('无可用全额投资方案')
  out[i]+=1;spent-=weights[i]
 return '\n'.join(map(str,out))
def quadratic(text):
 x=list(map(int,text.split()));out=[];memo={}
 for n in x[1:]:
  if n in memo:out.append(memo[n]);continue
  good=False
  if n>=0:
   for y in range(math.isqrt(n//3)+1):
    v=n-3*y*y;r=math.isqrt(v)
    if r*r==v:good=True;break
  memo[n]='yes' if good else 'no';out.append(memo[n])
 return '\n'.join(out)
