def meeting_both(text):
 m,n,x,y=map(int,text.split());a=[[0]*(m+1) for _ in range(n+1)];b=[[0]*(m+2) for _ in range(n+2)];a[1][1]=b[n][m]=1
 for j in range(1,n+1):
  for i in range(1,m-n+j+1):
   if (i,j)!=(1,1):a[j][i]=a[j-1][i]+a[j][i-1]
