  for i in range(m-n+j,0,-1):
   if (i,j)!=(m,n):b[j][i]=b[j+1][i]+b[j][i+1]
 return f'{a[y][x]}\n{b[y][x]}'
def meeting_one(text):return meeting_both(text).split()[0]
def life(text):
 x=list(map(int,text.split()));n,m,r=x[:3];a=[x[3+i*m:3+(i+1)*m] for i in range(n)];prefix=[[0]*(m+1) for _ in range(n+1)]
 for i in range(n):
  for j in range(m):prefix[i+1][j+1]=a[i][j]+prefix[i][j+1]+prefix[i+1][j]-prefix[i][j]
