 return '\n'.join(out)
def decipher(text):
 lines=text.splitlines();n=int(lines[0]);mapping=dict(line.split() for line in lines[1:n+1]);k=int(lines[n+1]);s=''.join(mapping.get(c,c) for c in lines[n+2]);k%=len(s);return s[k:]+s[:k]
def coins(text):
 v=list(map(int,text.split()));n=v[0];r=v[1:1+n];caps=v[1+n:];total=sum(r);covered=0;k=0
 for cap in sorted(caps,reverse=True):
  covered+=cap;k+=1
  if covered>=total:break
 dp=[{} for _ in range(k+1)];dp[0][0]=0
 for i,(cap,keep) in enumerate(zip(caps,r)):
  for used in range(min(i+1,k),0,-1):
   for amount,value in dp[used-1].items():
    at=min(total,amount+cap);dp[used][at]=max(dp[used].get(at,-1),value+keep)
 return f'{k} {total-dp[k][total]}'
def popcount_square(text):
 n=int(text);states={(0,True):(1,0,0)}
 # 各前缀维护数量、1的总数和1的个数平方和；不枚举0..n。
 for bit in bin(n)[2:]:
  next_states={}
  for (_,tight),(count,ones,square) in states.items():
   for b in range((int(bit) if tight else 1)+1):
    key=(0,tight and b==int(bit));c,o,s=next_states.get(key,(0,0,0));next_states[key]=(c+count,o+ones+b*count,s+square+2*b*ones+b*count)
  states=next_states
 return str(sum(v[2] for v in states.values()))
def cat(text):
 v=list(map(int,text.split()));n,a,b=v[:3];kernel=v[3:12];side=n-a+1;count=side*side//(b*b);weights=v[12:12+count];image=v[12+count:];offsets=[0,(a-1)//2,a-1];conv=[[sum(kernel[3*u+w]*image[(i+offsets[u])*n+j+offsets[w]] for u in range(3) for w in range(3)) for j in range(side)] for i in range(side)];pooled=[max(conv[u][w] for u in range(i,i+b) for w in range(j,j+b)) for i in range(0,side,b) for j in range(0,side,b)];return str(sum(x*y for x,y in zip(weights,pooled)))
def safe_coordinates(text):
 s=text.strip();count=0
 for a,b,c in itertools.combinations(range(1,len(s)),3):
  parts=[s[:a],s[a:b],s[b:c],s[c:]]
  if all(1<=len(t)<=3 and (t=='0' or t[0]!='0') and int(t)<=500 for t in parts):count+=1
 return str(count)
def squares(text):
 n=int(text);r=math.isqrt(n)
 if r*r==n:return '1'
 for a in range(r+1):
  b=math.isqrt(n-a*a)
